// Tree:   1
//        / \
//       2   3
void pre(Node n) {
    if (n == null) return;
    System.out.print(n.val);
    pre(n.left);
    pre(n.right);
}
// called as: pre(root)

Queue<Node> q = new ArrayDeque<>();
q.offer(root);   // Tree:    1
                 //         / \
                 //        2   3
                 //       /
                 //      4
while (!q.isEmpty()) {
    Node n = q.poll();
    System.out.print(n.val);
    if (n.left != null) q.offer(n.left);
    if (n.right != null) q.offer(n.right);
}

