void in(Node n) {
    if (n == null) return;
    in(n.left);
    System.out.print(n.val);
    in(n.right);
}
// called as: in(root)

// Tree:   1
//        / \
//       2   3
//      / \
//     4   5
void post(Node n) {
    if (n == null) return;
    post(n.left);
    post(n.right);
    System.out.print(n.val);
}
// called as: post(root)

int h(Node n) {
    if (n == null) return 0;
    return 1 + Math.max(h(n.left), h(n.right));
}
// Tree:  1
//       / \
//      2   3
//     /
//    4
System.out.println(h(root));

int leaves(Node n) {
    if (n == null) return 0;
    if (n.left == null && n.right == null) return 1;
    return leaves(n.left) + leaves(n.right);
}
// Tree:   1
//        / \
//       2   3
//      / \
//     4   5
System.out.println(leaves(root));

void f(Node n) {
    if (n == null) return;
    f(n.right);
    System.out.print(n.val);
    f(n.left);
}
// Tree:    1
//         / \
//        2   3
// called as: f(root)

int count(Node n) {
    if (n == null) return 0;
    return 1 + count(n.left) + count(n.right);
}
// Tree:  1
//       /   \
//      2     3
//       \
//        5
System.out.println(count(root) + " " + count(root.right));
